function validate([values]) {
  if (!Array.isArray(values) || values.length < 1 || values.length > 10) return 'values needs 1 to 10 shops.';
  const n = values[0].length;
  if (n < 1 || n > 10000) return 'Each shop has 1 to 10^4 items.';
  for (const row of values) {
    if (!Array.isArray(row) || row.length !== n) return 'Every shop must have the same number of items.';
    for (let j = 0; j < n; j++) {
      if (!Number.isInteger(row[j]) || row[j] < 1 || row[j] > 1000000) return 'Each value is an integer from 1 to 10^6.';
      if (j > 0 && row[j] > row[j - 1]) return 'Each shop must list its values from largest to smallest.';
    }
  }
  return null;
}

