function maxSpending(values) {
  const m = values.length;
  const n = values[0].length;
  const next = new Array(m).fill(n - 1);
  let total = 0;
  for (let day = 1; day <= m * n; day++) {
    let best = -1;
    for (let shop = 0; shop < m; shop++) {
      if (next[shop] < 0) continue;
      if (best === -1 || values[shop][next[shop]] < values[best][next[best]]) {
        best = shop;
      }
    }
    total += values[best][next[best]] * day;
    next[best]--;
  }
  return total;
}

