function maxSpending(values) {
  const m = values.length, n = values[0].length;
  const memo = new Map();
  const solve = bought => {
    const key = bought.join(',');
    if (memo.has(key)) return memo.get(key);
    const day = bought.reduce((a, b) => a + b, 0) + 1;
    let result = 0;
    for (let i = 0; i < m; i++) {
      if (bought[i] === n) continue;
      const after = bought.slice();
      after[i]++;
      result = Math.max(result, values[i][n - 1 - bought[i]] * day + solve(after));
    }
    memo.set(key, result);
    return result;
  };
  return solve(new Array(m).fill(0));
}

