function generate(rand, size) {
  const m = size === 'large' ? 5 + Math.floor(rand() * 6) : 1 + Math.floor(rand() * 4);
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * (m === 4 ? 2 : 3));
  const top = size === 'large' ? (rand() < 0.5 ? 1000000 : 50) : (rand() < 0.3 ? 3 : 9);
  const values = [];
  for (let i = 0; i < m; i++) {
    const row = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
    row.sort((a, b) => b - a);
    values.push(row);
  }
  return [values];
}
